from pathlib import Path
import json,csv
P=Path(__file__).resolve().parent;e=json.loads((P/'edits.json').read_text());n=json.loads((P/'notes.json').read_text())
def p(k,t):e[f'A0563-B{k:04d}']=t
p(2,'古圣是古老的爬行类星际种族。如今的年轻种族尚未发展起来时，他们便已建立先进文明。他们被描述为银河最早的智慧生命，也是最先横渡星海的种族，因此是银河中最古老的星际航行文明。')
p(4,'Eldar Exodite carving speculated to depict ancient creators with the various species they created 蛮荒灵族雕刻，据推测描绘了古老创造者及其创造的各个种族')
p(7,'据说，古圣拥有从容而冷静的智慧。他们研究群星，将占星术与天文学发展为深奥的科学。凭借对宇宙的理解，他们能够操纵其他维度，完成宏大的灵能工程。在年代不详的某个时期，他们创造了网道，使自己能避开亚空间潮汐，通达遥远世界。其科学如此先进，只需跨过网道之门，便可一步越过浩瀚星空；他们也借此将后裔散布到各地。')
p(11,'古圣相信，一切生命皆有其用途。他们促成许多新物种诞生，让数千颗属于自己的世界孕育生命。古史兰则认为，生命的目的在于完善凡人的灵魂。他们发现，若个体心智足够强大，死后便能在亚空间中保持完整，随心转世；前提是能够抵御混沌诸神那些病态意识，免遭其吞噬而失去自我。')
p(13,'古圣穿行宇宙的同时，许多更年轻、更好战的种族相继崛起，其中便有惧亡者。他们殖民其他星球时举步维艰，却见到古圣这般智慧超群、精通秘术的种族，能轻易迅速地拓殖群星，而且寿命漫长，近乎不朽。')
p(16,'惧亡者曾向古圣求取永生秘密，遭到拒绝。他们的母星恒星酷烈异常，使族人身患疾病，难以拓殖群星；古圣的拒绝更点燃了他们的仇恨。彼时，惧亡者帝国正陷于各王朝争斗的分裂战争。统治议会“三圣”认为，共同的外敌可以让整个种族重新团结，便借对古圣的敌意向其宣战。战利品与永生秘密的诱惑，使分离的王国再度联合，掀起后来所谓的“天堂之战”。嫉妒日渐加深，最终，惧亡者将整个文明的力量，都投入消灭古圣及其后裔的事业。')
p(20,'惨烈的战争接踵而至，惧亡者却始终无法战胜对手。他们虽技术先进，仍被精通网道传送的古圣一次次抢占先机。最终，惧亡者惨败，沦为古圣眼中不值一提的烦扰，被逐回光环群星边缘的黑暗地带，遭人遗忘。这种困守持续数百年。为寻找足以报复的武器，惧亡者开始研究自己的恒星，并发现栖息其中的古老存在。他们让这些存在获得实体，以本族语言称之为“星神”（C’tan），将其用作对抗古圣的武器。借助星神，惧亡者转化为冰冷的机械种族——太空死灵，重新向宿敌复仇。这次，古圣操控亚空间的力量，遇上了星神支配物质宇宙的权能，战局与从前截然不同。星神逐渐称霸银河，围困古圣堡垒，将其培育的种族当作牲畜吞食，填补永恒的饥渴。一个个世界遭焚毁，恒星被熄灭，整片星系被可怖的星神吞噬。')
p(22,'战争中，太空死灵军团攻入网道，在银河各处打击古圣。即便有着传说般的耐性与坚毅，古圣也渐感绝望，开始培育与亚空间联系更紧密的新生命，希望这些经过改造的种族，能驾驭灵能保护自己。许多战士种族由此诞生，据信包括灵族、克尼卜与拉杉。这些造物花了数千年才准备就绪，其间星神与太空死灵大军又抹去了宇宙中更多生命。')
p(24,'灵族是古圣最出色的学生，学会驾驭网道、磨炼完美心智，并在亚空间中保持不朽，因而不畏死亡。按灵族传说，古圣创造的乐土被星神亵渎；灵族将这些存在称为“因吉尔”。古圣的造物还包括早期人类——当时只是生态系统中栖息树间的野兽，古圣未赋予他们更重要的使命。灵族将这个时代称作“神战”：一方是星神支持的太空死灵，另一方是得到后继种族援助的古圣。')
p(26,'古圣终于集结反攻力量时，星神只剩四位，银河的大部分生命却已被抹灭。热血的年轻种族投入战场，令太空死灵节节败退：亚空间之力是他们的克星，使其难以挡住新攻势。作为回应，星神数百万年来首次联合，启动“大封印”，试图将至高天与物质宇宙永远隔绝，彻底抵消古圣的秘术。')
p(28,'然而，古圣似乎未曾预料的后果也在此时显现。年轻种族成长中的痛苦扰动亚空间，无形能量汇聚，古老的亚空间生灵变得凶残嗜掠，至高天日益险恶。它们试图穿过现实裂隙，侵入物质宇宙，迫使古圣继续创造新种族，保卫最后据点，其中便有绿皮、强韧的古兽人，以及善于仿造技术的太空猿猴。但此时为时已晚，古圣的星际网络已遭突破，最伟大的工程与力量枢纽，也被自身造物招来的亚空间恐怖吞没。其中最阴险的存在之一是奴役者：它们控制年轻种族的心智，为更多同类打开门户。奴役者瘟疫最终击垮了古圣的统治，使他们四散奔逃，其力量从此一蹶不振。')
p(31,'星神无休止的进攻，加上意外释放的亚空间灾祸，最终令古圣败亡、离散。幸存星神与太空死灵眼看着古圣文明覆灭，得偿夙愿。而在星神吞噬残存生命、又彼此相食之际，寂静王斯扎拉克发动反叛，将星神击碎。战后的权力真空中，人类等古圣未曾重视的造物，继续以出乎意料的方式发展。银河霸权最终落入曾与古圣并肩作战的灵族手中。他们在创造者灭亡后幸存，也见证太空死灵反抗星神，随后进入大休眠。关于古圣的传说仍在流传：凯洛尔方舟世界的符文歌者称，网道由这一古老始祖种族创造，用以穿行群星。另有传闻称，太空死灵领主无尽者塔拉辛所用的移情泯灭杖，可能采用古圣设计的技术制成。')
p(34,'古圣以生物工程培育了银河中的许多物种。已知由其创造的年轻种族，简列如下：')
p(35,'Aeldari 艾达灵族')
p(37,"K'nib 克尼卜")
p(44,'《战锤40,000》第一版资料中，尚未出现古圣这一设定。当时在《战锤40,000：行商浪人》及第一版《泰坦圣典》中，承担相近角色的是史兰或古史兰：他们曾早期接触灵族，传授建造网道的技术。前一本还称，史兰曾对多个种族进行基因改造，并暗示太空猿猴也是其造物。第三版从《圣典：太空死灵》开始提及古圣，进一步说明他们改造早期生命、与太空死灵展开远古战争的背景。第四版《圣典：灵族》与《圣典：混沌恶魔》也记述古圣教导灵族使用网道；第五版《圣典：黑暗灵族》则明确称，网道最初便由古圣创造。')
p(48,'《混沌圣典》的“色孽”卷，在“诞生回响”一章中，也以“初代”之名部分提及古圣。该节讲述灵族由一道道光影般的身影扶植成长；这些身影属于古老而强大的种族。据说，初代最先伸手触及群星，比诸神更古老，却仍会死亡，仍受时间约束。他们离开灵族，回归星空，让这些受其看护的后辈自行发展数千年。后来，初代乘着奇异巨舰归来，舰身破败、伤痕累累，光芒黯淡，阴影消散。他们正与因吉尔鏖战不休，此番返回，是为检视灵族是否已准备好迎接战争。初代鼓励后辈凝聚灵能，创造源自亚空间的生灵，用作对抗那些吸血般吞噬生命的星光之神的武器。战争漫长，初代日渐稀少，在灵族中的影响也随之衰退。失去创造者的智慧引导后，这些有意识的亚空间武器，逐渐变成非物质界中活生生的诸神，是这一类存在中最早的一批。初代消失后，只有灵族英雄埃尔达纳什与乌斯拉纳什能够驾驭这些亚空间诸神，对抗敌人，直到他们被迫躲避一场恶魔瘟疫。此后，据说灵族继承、改进并完善了初代测量亚空间、预判其变化的技艺。')
p(50,'《异形学》也可能影射古圣。书中称，色孽诞生前曾有“古神”，在天堂与地狱同“星魔”交战。按书内作者库尔多·萨尔瓦多的说法，星魔最终获胜，古神尽被屠戮，唯有一位幸存。他躲藏起来，继续照旧东改西试，摆弄生命与事物。完成工作后，他遁入亚空间，隐匿观察。等“长耳朵”们孕育出“她”——色孽——新神便把这位残存古圣斩成数百万块，将碎片踢入冰冷虚空，让它们“像往常一样苟延残喘……”萨尔瓦多称，这些残片后来被称为“本影”。这位被迫残存的存在，也与赫鲁德神系中的卡赫有许多相似之处。')
p(52,'相关资料称，即使古圣文明已经覆灭，星神仍对其怀有顽固的仇恨，积极搜寻偏远世界上可能残存的退化后裔。《圣典：太空死灵》甚至建议，在桌面战棋中，可以用蜥蜴人军队的模型代替这些古圣后裔。')
n.update({'A0563-B0007':'cold-blooded wisdom 按爬行种族叙述译为从容冷静的智慧，不额外引申为残酷无情；psychic engineering 修正灵能工程。','A0563-B0011':'Old Slann（古史兰）与 Old Ones（古圣）在不同版本材料中角色相近，按本篇末尾版本说明分列，不消去术语差异。','A0563-B0022':'ranked among their number 指属于其列，原译名列前茅错误增加优劣排名。','A0563-B0024':'早期人类与古圣的关系照所给英文记载；tree beasts 为树栖生物，不把当前人类直接等同现代动物物种。','A0563-B0026':'大封印暂译 great warding，明确其意图为隔绝亚空间；仅剩四位星神为该段采用的叙述阶段与版本口径，不概括为全设定恒定数量。','A0563-B0031':'Trazyn the Infinite采用官方无尽者塔拉辛；Empathic Obliterator与词表统一移情泯灭杖。','A0563-B0044':'原译将 Warhammer 40,000: Rogue Trader 与 Codex Titanicus 两本书误合为一个书名；已拆分，保留各版本差别。Eldar旧版书名对应灵族，Aeldari对应艾达灵族。','A0563-B0048':'该段叙述出自特定出版物的神话视角，并非独立核实后的唯一历史。','A0563-B0050':'departed into the Warp 指进入亚空间，原译离开亚空间方向相反；Kurdo Salvador是该书叙事中的作者身份，不能当作现实出版作者。','A0563-B0052':'backwater worlds 指偏远落后世界，不是死水世界；placeholder指桌面模型替代用途，不是在设定中断言蜥蜴人就是古圣后代。'})
rows=list(csv.DictReader((P/'terms.tsv').open(),delimiter='\t'));cols=list(rows[0]);by={r[cols[0]].casefold():r for r in rows}
for en,zh in [('Old Slann','古史兰'),('Slann','史兰'),('Necrontyr','惧亡者'),('Triarch','三圣'),("C'tan",'星神'),("K'nib",'克尼卜'),('Rashan','拉杉'),('Yngir','因吉尔'),('God War','神战'),('great warding','大封印'),('Krork','古兽人'),('Enslaver Plague','奴役者瘟疫'),('Szarekh','斯扎拉克'),('Kaelor','凯洛尔'),('First Ones','初代'),('Liber Chaotica','混沌圣典'),('Xenology','异形学'),('Kurdo Salvador','库尔多·萨尔瓦多'),('Umbra','本影'),('Qah','卡赫'),('Hrud','赫鲁德')]:
 by.setdefault(en.casefold(),dict(zip(cols,[en,zh,'暂定·官方待核','所给英文底稿','篇0563','依具体历史与版本语境定译；不同传说不合并为单一确证史实。'])))
with (P/'terms.tsv').open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=cols,delimiter='\t');w.writeheader();w.writerows(by.values())
for fn,obj in [('edits.json',e),('notes.json',n)]:(P/fn).write_text(json.dumps(obj,ensure_ascii=False,indent=2))
rv=set(json.loads((P/'reviewed.json').read_text()))|{563};(P/'reviewed.json').write_text(json.dumps(sorted(rv)))
(P/'partial_progress.json').write_text(json.dumps({'article':563,'read_through_block':52,'complete':True},ensure_ascii=False,indent=2))
print('551-565 complete',len(e),'edits')
